//
// SQLite via node:sqlite is tried first (Node >= 22.5); if that module is not
// available we fall back to a small append-only JSON journal. Either way the
// data lives on disk (DB_PATH, backed by the api_data volume) and survives
// restarts of the container.
const fs = require('node:fs');
const path = require('node:path');

const DB_PATH = process.env.DB_PATH || '/data/shopping.db';

function nowIso() {
  return new Date().toISOString();
}

function createSqliteStore() {
  const { DatabaseSync } = require('node:sqlite');
  const file = DB_PATH.replace(/\.[^./]+$/, '') + '.sqlite';
  fs.mkdirSync(path.dirname(file), { recursive: true });
  const db = new DatabaseSync(file);
  db.exec(`
    CREATE TABLE IF NOT EXISTS items (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      bought INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      bought_at TEXT
    );
  `);
  const insert = db.prepare('INSERT INTO items (name, bought, created_at) VALUES (?, 0, ?)');
  const get = db.prepare('SELECT * FROM items WHERE id = ?');
  const all = db.prepare('SELECT * FROM items ORDER BY id');
  const setBought = db.prepare('UPDATE items SET bought = ?, bought_at = ? WHERE id = ?');
  const del = db.prepare('DELETE FROM items WHERE id = ?');

  const store = {
    kind: 'sqlite',
    file,
    list() {
      return all.all().map((r) => ({ id: Number(r.id), name: r.name, bought: !!r.bought }));
    },
    get(id) {
      const r = get.get(id);
      return r ? { id: Number(r.id), name: r.name, bought: !!r.bought } : null;
    },
    add(name) {
      const info = insert.run(name, nowIso());
      return store.get(Number(info.lastInsertRowid));
    },
    setBought(id, bought) {
      const info = setBought.run(bought ? 1 : 0, bought ? nowIso() : null, id);
      return Number(info.changes) ? store.get(id) : null;
    },
    remove(id) {
      return Number(del.run(id).changes) > 0;
    },
    close() {
      db.close();
    },
  };
  return store;
}

function createJsonStore() {
  const file = DB_PATH.replace(/\.[^./]+$/, '') + '.json';
  fs.mkdirSync(path.dirname(file), { recursive: true });
  let state = { nextId: 1, items: [] };
  if (fs.existsSync(file)) {
    try {
      const parsed = JSON.parse(fs.readFileSync(file, 'utf8'));
      if (parsed && Array.isArray(parsed.items)) state = { nextId: parsed.nextId || 1, items: parsed.items };
    } catch (e) {
      console.error('could not read journal, starting empty:', e.message);
    }
  }
  let pending = false;
  function persist() {
    // Atomic-ish write: temp file + rename, so a crash never truncates the data.
    const tmp = file + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(state));
    fs.renameSync(tmp, file);
    pending = false;
  }
  function touch() {
    if (!pending) {
      pending = true;
      // written synchronously on every mutation below for maximum durability
    }
    persist();
  }
  const store = {
    kind: 'json',
    file,
    list() {
      return state.items.map((i) => ({ id: i.id, name: i.name, bought: !!i.bought }));
    },
    get(id) {
      const i = state.items.find((x) => x.id === id);
      return i ? { id: i.id, name: i.name, bought: !!i.bought } : null;
    },
    add(name) {
      const item = { id: state.nextId++, name, bought: false, created_at: nowIso(), bought_at: null };
      state.items.push(item);
      touch();
      return store.get(item.id);
    },
    setBought(id, bought) {
      const i = state.items.find((x) => x.id === id);
      if (!i) return null;
      i.bought = !!bought;
      i.bought_at = bought ? nowIso() : null;
      touch();
      return store.get(id);
    },
    remove(id) {
      const n = state.items.length;
      state.items = state.items.filter((x) => x.id !== id);
      if (state.items.length === n) return false;
      touch();
      return true;
    },
    close() {
      persist();
    },
  };
  return store;
}

function openStore() {
  try {
    const s = createSqliteStore();
    console.log(`storage: sqlite at ${s.file}`);
    return s;
  } catch (e) {
    console.warn('sqlite unavailable, using json journal:', e.message);
    const s = createJsonStore();
    console.log(`storage: json at ${s.file}`);
    return s;
  }
}

module.exports = { openStore };
