'use strict';
// Shared shopping list - HTTP API.
//
// Contract (see docs/API.md):
//   GET    /api/health                 -> {ok:true}
//   GET    /api/items                  -> {version, items:[{id,name,bought}]}
//   GET    /api/items?since=<version>  -> long-poll (up to 25s) until version > since
//   POST   /api/items {name}           -> 201 {id,name,bought}
//   PATCH  /api/items/<id> {bought}    -> 200 {id,name,bought} | 404
//   DELETE /api/items/<id>             -> 204 | 404
//
// `version` is a monotonic integer bumped on every change; it is durable too,
// so a peer's since= value is always meaningful.
const http = require('node:http');
const { openStore } = require('./db');

const PORT = Number(process.env.PORT || 3000);
const HOST = process.env.HOST || '0.0.0.0';
const LONG_POLL_MS = Number(process.env.LONG_POLL_MS || 25000);
const MAX_NAME = 500;

const store = openStore();
let version = 1 + store.list().length; // any durable monotonic start is fine
const waiters = new Set();

function bump() {
  version += 1;
  for (const w of waiters) {
    if (w.since < version) {
      waiters.delete(w);
      w.flush();
    }
  }
}

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, PATCH, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': '*',
  'Access-Control-Max-Age': '86400',
};

function send(res, status, body, extra) {
  const headers = { ...CORS, 'Cache-Control': 'no-store', ...(extra || {}) };
  if (body === undefined || body === null) {
    res.writeHead(status, headers);
    res.end();
    return;
  }
  const json = JSON.stringify(body);
  headers['Content-Type'] = 'application/json; charset=utf-8';
  headers['Content-Length'] = Buffer.byteLength(json);
  res.writeHead(status, headers);
  res.end(json);
}

function fail(res, status, message) {
  send(res, status, { error: message });
}

function readBody(req, limit = 64 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > limit) {
        reject(Object.assign(new Error('body too large'), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('end', () => {
      const raw = Buffer.concat(chunks).toString('utf8').trim();
      if (!raw) return resolve({});
      try {
        const parsed = JSON.parse(raw);
        resolve(parsed && typeof parsed === 'object' ? parsed : {});
      } catch {
        reject(Object.assign(new Error('body is not valid JSON'), { status: 400 }));
      }
    });
    req.on('error', reject);
  });
}

function snapshot() {
  return { version, items: store.list() };
}

function parseBought(value) {
  if (typeof value === 'boolean') return value;
  if (value === 1 || value === 0) return !!value;
  if (typeof value === 'string') {
    const v = value.trim().toLowerCase();
    if (['true', '1', 'yes', 'on', 'checked'].includes(v)) return true;
    if (['false', '0', 'no', 'off', 'unchecked'].includes(v)) return false;
  }
  return null;
}

async function handle(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const pathname = url.pathname.replace(/\/+$/, '') || '/';

  if (req.method === 'OPTIONS') return send(res, 204);

  if (pathname === '/' || pathname === '/api' || pathname === '/api/') {
    return send(res, 200, {
      service: 'shopping-list-api',
      endpoints: ['GET /api/health', 'GET /api/items', 'POST /api/items', 'PATCH /api/items/<id>', 'DELETE /api/items/<id>'],
    });
  }

  if (pathname === '/api/health' || pathname === '/health') {
    return send(res, 200, { ok: true, service: 'api', version, storage: store.kind, items: store.list().length });
  }

  if (pathname === '/api/items' || pathname === '/items') {
    if (req.method === 'GET' || req.method === 'HEAD') {
      const rawSince = url.searchParams.get('since');
      if (rawSince === null || rawSince === '') return send(res, 200, snapshot());
      const since = Number(rawSince);
      if (!Number.isFinite(since)) return fail(res, 400, 'since must be a number');
      if (since < version) return send(res, 200, snapshot());
      // Long poll: answer as soon as anything changes (or after LONG_POLL_MS).
      return await new Promise((resolve) => {
        const done = () => {
          clearTimeout(timer);
          waiters.delete(waiter);
          if (!res.writableEnded) send(res, 200, snapshot());
          resolve();
        };
        const timer = setTimeout(() => {
          waiters.delete(waiter);
          if (!res.writableEnded) send(res, 200, snapshot());
          resolve();
        }, LONG_POLL_MS);
        const waiter = { since, flush: done };
        waiters.add(waiter);
        res.on('close', () => {
          clearTimeout(timer);
          waiters.delete(waiter);
          resolve();
        });
      });
    }

    if (req.method === 'POST') {
      const body = await readBody(req);
      const name = typeof body.name === 'string' ? body.name.trim() : body.name === undefined ? '' : String(body.name).trim();
      if (!name) return fail(res, 400, 'name is required');
      if (name.length > MAX_NAME) return fail(res, 400, `name must be at most ${MAX_NAME} characters`);
      const item = store.add(name);
      bump();
      return send(res, 201, item, { Location: `/api/items/${item.id}` });
    }

    return fail(res, 405, 'method not allowed');
  }

  const m = pathname.match(/^\/api\/items\/(\d+)$/);
  if (m) {
    const id = Number(m[1]);
    if (req.method === 'GET') {
      const item = store.get(id);
      return item ? send(res, 200, item) : fail(res, 404, 'no such item');
    }
    if (req.method === 'PATCH' || req.method === 'PUT') {
      const body = await readBody(req);
      if (!Object.prototype.hasOwnProperty.call(body, 'bought')) return fail(res, 400, 'bought is required');
      const bought = parseBought(body.bought);
      if (bought === null) return fail(res, 400, 'bought must be a boolean');
      const item = store.setBought(id, bought);
      if (!item) return fail(res, 404, 'no such item');
      bump();
      return send(res, 200, item);
    }
    if (req.method === 'DELETE') {
      const ok = store.remove(id);
      if (!ok) return fail(res, 404, 'no such item');
      bump();
      return send(res, 204);
    }
    return fail(res, 405, 'method not allowed');
  }

  return fail(res, 404, 'not found');
}

const server = http.createServer((req, res) => {
  handle(req, res).catch((err) => {
    console.error(`${req.method} ${req.url} failed:`, err);
    if (!res.headersSent) send(res, err.status || 500, { error: err.message || 'internal error' });
    else res.end();
  });
});

server.headersTimeout = 120000;
server.requestTimeout = 0; // long polls are expected
server.keepAliveTimeout = 65000;

server.listen(PORT, HOST, () => {
  console.log(`shopping-list api listening on http://${HOST}:${PORT} (storage=${store.kind}, version=${version})`);
});

function shutdown(signal) {
  console.log(`${signal}: shutting down`);
  for (const w of waiters) {
    try {
      w.flush();
    } catch {}
  }
  waiters.clear();
  server.close(() => {
    try {
      store.close();
    } catch {}
    process.exit(0);
  });
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
